using System;
using System.Linq;
using System.Windows.Controls;
partial class TerminalWindow {
 TextBlock quotaStatus,quotaCountdown,quotaHistory,limitStatus;
 void BuildDownloadLimit(Panel body,MonitorConfig cfg){SettingDescription(body,"限制本机所有非回环 TCP/UDP 入站数据的平均接收速率，浏览器、下载器及视频等共享一个上限。使用 WinDivert 签名驱动；首次启用时由系统 PowerShell 校验组件并复制到 Program Files 受保护目录，需要管理员授权。不会自动启动，退出桌宠会停止。它在本机接收后整形，短时峰值、协议重传和 VPN 虚拟网卡可能使物理网卡读数不同，不能保证路由器侧瞬时流量严格不超过数值。尚未进行整机限速实测，首次使用前请保存正在下载的任务。");var rate=TaskbarInput(body,"下载上限（MiB/s）",cfg.DownloadLimitMiB.ToString(System.Globalization.CultureInfo.InvariantCulture),100);limitStatus=Text(assistant.Limiter.Status,13);body.Children.Add(limitStatus);Button(body,"保存限速数值",()=>{double v=TaskbarNumber(rate);if(Double.IsNaN(v)||Double.IsInfinity(v)||v<.1||v>10000)throw new ArgumentException("下载上限0.1–10000 MiB/s。");SaveMonitor(()=>cfg.DownloadLimitMiB=v);});Button(body,"启用整机下载限速（管理员授权）",()=>{if(System.Windows.MessageBox.Show(this,"将使用系统 PowerShell 校验组件，在 Program Files 创建受保护副本后加载 WinDivert 签名驱动，对整机入站 TCP/UDP 数据实施平均限速，可能影响 VPN、视频与下载。可随时停止；退出桌宠也会停止。是否继续？","启用下载限速",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Question)!=System.Windows.MessageBoxResult.Yes)return;double v=TaskbarNumber(rate);assistant.Limiter.Start(home,v);SaveMonitor(()=>cfg.DownloadLimitMiB=v);limitStatus.Text=assistant.Limiter.Status;});Button(body,"停止限速 · 恢复正常速度",()=>{assistant.Limiter.Dispose();limitStatus.Text=assistant.Limiter.Status;});}

 void BuildQuotaSettings(Panel body,MonitorConfig cfg){var q=cfg.Quota??(cfg.Quota=new CodexQuotaConfig());MonitorToggle(body,"监测 Codex 五小时和周额度",()=>q.Enabled,v=>q.Enabled=v);SettingDescription(body,"先确认本机额度程序与数据目录，再通过已登录的 Codex 官方 app-server 每60秒查询，不读取或保存登录令牌，不消耗对话额度。任务栏显示的是剩余百分比；超过5分钟未核验或窗口已重置则显示—。额度报警配合警觉动作与已核实原声，并遵守总音量和全屏静音。");quotaStatus=Text("",12);body.Children.Add(quotaStatus);quotaCountdown=Text("",15);body.Children.Add(quotaCountdown);Button(body,"额度与重置提醒设置 →",()=>{memoTab="额度与重置";ShowPage("侦探备忘录");});var connection=body;var executable=TaskbarInput(connection,"Codex.exe（留空自动找）",q.Executable,280);Button(connection,"选择 Codex.exe…",()=>{using(var picker=new System.Windows.Forms.OpenFileDialog{Filter="Codex程序|codex.exe|可执行文件|*.exe"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)executable.Text=picker.FileName;});var codexHome=TaskbarInput(connection,"Codex数据目录",q.Home,280);Button(connection,"选择 Codex 数据目录…",()=>{using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="选择含 Codex 配置的 CODEX_HOME 目录；无需打开或复制 auth.json"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)codexHome.Text=picker.SelectedPath;});SettingDescription(connection,"若独立启动后提示未登录，请选择与你当前 Codex 相同的数据目录；默认沿用启动环境的 CODEX_HOME。目录仅保存路径，不复制其中内容。");SettingDescription(body,"倒计时基于官方返回的预计重置时间，每秒更新；每60秒查询额度。周额度提前回升会单独记录为疑似重置/调整。记录首次检测时间和前次核验时间，无法保证官方实际重置的精确时刻。账号无法识别或切换时不推断重置，历史最多100条，保存在用户数据中。");quotaHistory=Text("",12);var history=new Expander{Header="重置记录 · 最近8条",Content=quotaHistory,Margin=new System.Windows.Thickness(0,8,0,8)};body.Children.Add(history);var buttons=new WrapPanel{Margin=new System.Windows.Thickness(0,10,0,0)};body.Children.Add(buttons);Button(buttons,"保存额度连接设置",()=>{if(!String.IsNullOrWhiteSpace(executable.Text))CodexQuotaReader.FindExecutable(executable.Text);if(!String.IsNullOrWhiteSpace(codexHome.Text)&&!System.IO.Directory.Exists(codexHome.Text))throw new ArgumentException("Codex数据目录不存在。");SaveMonitor(()=>{q.Home=codexHome.Text.Trim();q.Executable=executable.Text.Trim();});assistant.QuotaReader.RefreshNow();});Button(buttons,"将两项额度加入任务栏",()=>{SaveMonitor(()=>{foreach(string key in new[]{"codex5h","codex7d"})if(!cfg.TaskbarItems.Contains(key))cfg.TaskbarItems.Add(key);});taskbarDraft=null;ShowPage("任务栏外观");});Button(buttons,"导出重置记录…",()=>{using(var picker=new System.Windows.Forms.SaveFileDialog{Filter="重置报告|*.txt",FileName="Codex额度重置记录.txt"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){string report;lock(assistant)report=String.Join("\r\n\r\n",(q.ResetHistory??new System.Collections.Generic.List<CodexQuotaReset>()).Select(x=>x.Report()));System.IO.File.WriteAllText(picker.FileName,"记录时间是首次检测时刻，非官方实际执行时刻。\r\n\r\n"+report,new System.Text.UTF8Encoding(true));}});Button(buttons,"授权并连接额度服务…",()=>{var identity=assistant.QuotaReader.Trust.Inspect(executable.Text.Trim(),codexHome.Text.Trim());if(System.Windows.MessageBox.Show(this,"将允许后台启动以下程序读取额度。请确认来源可信。\n\n程序："+identity.Executable+"\n数据目录："+identity.Home+"\nSHA-256："+identity.Sha256+"\n\n授权只对当前Windows账户和本机有效，会加密保存在本地数据目录。相同程序无需每次确认；程序更新或路径改变后需重新确认。", "授权额度程序",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Question)!=System.Windows.MessageBoxResult.Yes)return;assistant.QuotaReader.Trust.Approve(identity);SaveMonitor(()=>{q.Executable=identity.Executable;q.Home=identity.Home;q.Enabled=true;});executable.Text=q.Executable;codexHome.Text=q.Home;assistant.QuotaReader.RefreshNow();quotaStatus.Text="已授权，下次采样将核验程序内容后读取额度。";});Button(buttons,"撤销额度程序授权",()=>{assistant.QuotaReader.Trust.Revoke();SaveMonitor(()=>q.Enabled=false);});Button(buttons,"立即刷新额度",()=>{assistant.QuotaReader.RefreshNow();quotaStatus.Text="已请求重新核验，稍后显示结果。";});}
 void BuildExitConnection(Panel body,MonitorConfig cfg){SettingDescription(body,"出口查询仅使用已授权的 ipwho.is。系统代理适用于 FlClash 系统代理模式；TUN 模式可直连。不会在代理失败时偷偷改用直连，避免将其他出口误判为 VPN 正常。");var mode=TaskbarChoice(body,"出口查询通道",new[]{"跟随 Windows 系统代理","直连（适用于 TUN）","手动 HTTP 代理"},cfg.ExitProxyMode=="direct"?1:cfg.ExitProxyMode=="manual"?2:0);var address=TaskbarInput(body,"HTTP代理地址",cfg.ExitProxyAddress,290);Button(body,"保存出口连接方式",()=>{string selected=new[]{"system","direct","manual"}[Math.Max(0,mode.SelectedIndex)];NetworkExit.Proxy(selected,address.Text.Trim());SaveMonitor(()=>{cfg.ExitProxyMode=selected;cfg.ExitProxyAddress=address.Text.Trim();});});}
}
